from src.malignant.linkage import qualify_linkage
def test_same_patient_without_cell_link_rejected(): assert qualify_linkage()=='MALIGNANT_NOT_OBSERVABLE'
def test_same_sample_without_cell_link_rejected(): assert qualify_linkage()=='MALIGNANT_NOT_OBSERVABLE'
def test_same_tumour_without_cell_link_rejected(): assert qualify_linkage()=='MALIGNANT_NOT_OBSERVABLE'
def test_same_cluster_without_cell_link_rejected(): assert qualify_linkage()=='MALIGNANT_NOT_OBSERVABLE'
