def test_validated_same_cell_ground_truth(): assert qualify_linkage(same_cell=True,malignant_validated=True,public_inputs=True,direct_ground_truth=True)=='MALIGNANT_GROUND_TRUTH'
def test_reproducible_cell_cnv_e4(): assert qualify_linkage(same_cell=True,malignant_validated=True,public_inputs=True,method_documented=True,reference_available=True)=='MALIGNANT_REPRODUCIBLE_INFERENCE'
